def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp_last = history[-1][1]
    my_last = history[-1][0]
    opp_prev = history[-2][1]
    my_prev = history[-2][0]

    opp_def = 0
    my_def = 0
    cc = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1
        if m == 'C' and o == 'C':
            cc += 1

    if n >= 95:
        if opp_def * 3 <= n:
            return 'D'
        if opp_last == 'C':
            return 'D'
        return 'D'

    if opp_last == 'D' and opp_prev == 'D':
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.2:
                return 'D'
            return 'C'

    if opp_last == 'C':
        recent = history[-6:]
        rd = 0
        for m, o in recent:
            if o == 'D':
                rd += 1
        if rd >= 3:
            return 'D'
        if my_last == 'D':
            if opp_def * 4 > n:
                if rng.random() < 0.6:
                    return 'D'
                return 'C'
            return 'C'
        if cc >= n - 2:
            return 'C'
        if opp_def == 0:
            if n >= 85:
                return 'D'
            return 'C'
        if opp_def * 5 <= n:
            if rng.random() < 0.05:
                return 'D'
            return 'C'
        return 'C'

    return 'C'
